fn perturb_normal(p0: vec3<f32>, p1: vec3<f32>, p2: vec3<f32>, uv0: vec2<f32>, uv1: vec2<f32>, uv2: vec2<f32>, n: vec3<f32>, nm_sample: vec2<f32>) -> vec3<f32> {
    let e1 = p1 - p0;
    let e2 = p2 - p0;
    let du1 = uv1 - uv0;
    let du2 = uv2 - uv0;
    let det = du1.x * du2.y - du1.y * du2.x;
