    let l2 = dot(world_nm, world_nm);
    return select(n, world_nm * inverseSqrt(l2), l2 > 1e-6);
}

fn shade_sponza_pbr(world_pos: vec3<f32>, geom_n: vec3<f32>, shaded_n: vec3<f32>, albedo: vec3<f32>, rough_in: f32, metallic: f32, emissive: vec3<f32>, ao: f32, flags: u32, normal_var: f32, frag_xy: vec2<f32>) -> vec3<f32> {
