    let l = frame_params.sun_dir_illum.xyz;
    let sun_rad = frame_params.sun_color_shaft.rgb * frame_params.sun_dir_illum.w;
    let rough = sqrt(clamp(rough_in * rough_in + normal_var * 0.35, 0.03, 0.96));
